extern int RtUiFactory2Register();         // ui_factory_wave28.cpp (FACTUI2)

// 2026-09-12, VTABLE BATCH 3 - the UI::*Element widget runtime, first half.
// Thirteen classes, one file each (runtime/src/ui/<class>element.cpp), each
